// Generated by scripts/build-glossary-data.mjs from content-source/glossary. Do not edit by hand.
export const GLOSSARY_SHARD = Object.freeze({"bitcoin-halving":{"slug":"bitcoin-halving","cat":"basics","en":"Bitcoin halving","contentLocale":"ko","term":"비트코인 반감기(Halving)","aka":["반감기","Halving","비트코인 반감기"],"short":"비트코인 반감기는 21만 블록(약 4년)마다 채굴 보상이 절반으로 줄어드는 프로토콜 규칙으로, 새 비트코인의 발행 속도를 낮춥니다.","body":[[["비트코인","bitcoin"],"은 처음 블록당 50 BTC를 보상으로 발행했고, 이후 반감기마다 25, 12.5, 6.25 BTC로 줄었습니다. 2024년 4월 반감기 이후 블록 보상은 3.125 BTC입니다. 이 일정은 코드에 정해져 있어 누군가 임의로 바꿀 수 없습니다."],"반감기는 날짜가 아니라 블록 높이로 정해집니다. 블록이 평균 약 10분마다 생성되므로 대략 4년 간격이 되지만, 정확한 시점은 실제 블록 생성 속도에 따라 조금씩 달라집니다.",["반감기 이후 ",["채굴","mining"],"자의 수익 구조가 바뀌고 신규 공급이 줄어들기 때문에 시장의 관심이 큽니다. 다만 과거 반감기 이후의 가격 흐름이 앞으로도 반복된다는 보장은 없습니다. 반감기는 공급 규칙을 이해하는 개념으로 보는 것이 정확합니다."]],"example":"블록 보상이 3.125 BTC일 때 하루에 약 144개 블록이 생성된다면 하루 신규 발행량은 약 450 BTC입니다. 반감기 이전 보상 6.25 BTC 기준으로는 약 900 BTC였습니다. 다음 반감기에 보상이 1.5625 BTC로 줄면 하루 발행량은 약 225 BTC가 됩니다. 실제 블록 수는 날마다 조금씩 다르므로 이 숫자는 평균적인 추정치입니다.","mistakes":["반감기가 특정 날짜에 고정돼 있다고 생각하지만 실제로는 블록 높이로 결정됩니다.","반감기를 비트코인 가격이나 보유 수량이 절반으로 줄어드는 사건으로 오해합니다.","과거 반감기 이후 흐름을 그대로 반복될 공식처럼 받아들입니다."],"faq":[{"q":"비트코인 반감기는 언제 오나요?","a":"21만 블록마다 오며, 평균적으로 약 4년 간격입니다. 가장 최근은 2024년 4월이었고, 다음 반감기 시점은 블록 생성 속도에 따라 추정치가 조금씩 달라집니다."},{"q":"반감기가 계속되면 비트코인 발행은 언제 끝나나요?","a":"보상이 계속 절반으로 줄어 결국 사토시 단위 이하가 되면 새 발행이 멈춥니다. 그 시점은 대략 2140년 무렵으로 추정되며 이후 채굴자는 거래 수수료로 보상을 받습니다."}],"title":"비트코인 반감기란? 뜻과 채굴 보상 변화","description":"비트코인 반감기의 뜻, 21만 블록마다 채굴 보상이 절반이 되는 원리, 2024년 이후 블록 보상 3.125 BTC의 의미를 정리합니다.","related":[["bitcoin","비트코인(Bitcoin, BTC)","비트코인(BTC)은 2009년 운영을 시작한 최초의 암호화폐로, 작업증명 블록체인 위에서 중앙 관리자 없이 발행되며 총발행량이 2,100만 개로 정해져 있습니다."],["mining","채굴(Crypto Mining)","채굴은 작업증명 블록체인에서 컴퓨터 연산으로 새 블록을 만들고 거래를 확정하는 과정으로, 채굴자는 그 대가로 블록 보상과 거래 수수료를 받습니다."],["proof-of-work","작업증명(Proof of Work, PoW)","작업증명(PoW)은 채굴자가 대량의 연산으로 특정 조건을 만족하는 해시값을 먼저 찾아내야 블록을 추가할 수 있게 하는 블록체인 합의 방식입니다."],["hash-rate","해시레이트(Hash rate)","해시레이트는 작업증명 블록체인에서 채굴 장비들이 1초에 계산하는 해시의 총량으로, 네트워크의 채굴 경쟁 강도와 보안 수준을 보여 주는 지표입니다."],["satoshi","사토시(Satoshi, sats)","사토시는 비트코인의 최소 단위로, 1 BTC는 1억(100,000,000) 사토시이며 1 사토시는 0.00000001 BTC입니다."]],"lesson":null,"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"stop-loss":{"slug":"stop-loss","cat":"trading","en":"Stop-loss order","contentLocale":"ko","term":"손절 주문(Stop-Loss)","aka":["손절","스탑로스","Stop Loss","손절매"],"short":"손절 주문(스탑로스)은 가격이 미리 정한 수준까지 불리하게 움직이면 자동으로 포지션을 정리해 손실을 제한하는 주문입니다.","body":[["손절 주문에는 트리거 가격이 있습니다. 가격이 트리거에 닿으면 ",["시장가","market-order"]," 또는 ",["지정가 주문","limit-order"],"이 실행됩니다. 시장가 방식은 체결이 거의 확실하지만 급락 구간에서 ",["슬리피지","slippage"],"가 생길 수 있고, 지정가 방식은 가격은 지켜도 체결되지 않을 위험이 있습니다."],["선물 거래에서는 트리거 기준을 ",["최근 체결가","last-price"],"로 할지 ",["마크 가격","mark-price"],"으로 할지 선택할 수 있는 경우가 많습니다. 손절은 ",["강제청산","liquidation"],"보다 먼저 실행되도록 설정해야 의미가 있습니다. 강제청산은 증거금 대부분을 잃고 추가 수수료가 붙을 수 있기 때문입니다."],"손절 위치는 감이 아니라 계획으로 정합니다. 차트상 의미 있는 지지·저항 아래나 위에 두고, 그 손절 폭에서 감당할 손실 금액을 기준으로 포지션 크기를 역산하는 방식이 많이 쓰입니다."],"example":"계좌가 2,000 USDT이고 한 거래의 최대 손실을 2%인 40 USDT로 정했다고 가정해 보겠습니다. SOL을 160 USDT에 사고 손절을 152 USDT에 두면 손절 폭은 8 USDT, 5%입니다. 40 USDT를 8로 나누면 5 SOL, 즉 800 USDT어치까지 살 수 있습니다. 가격이 152 USDT에 닿으면 손실은 약 40 USDT이며, 시장가 체결 시 슬리피지와 수수료만큼 조금 더 커질 수 있습니다.","mistakes":["손절가에 가까워지면 손절 주문을 취소하거나 더 아래로 내립니다.","레버리지 포지션에서 손절을 강제청산 가격보다 멀리 설정합니다.","손절 폭은 정하면서 포지션 크기는 손실 한도와 연결하지 않습니다."],"faq":[{"q":"손절 주문을 걸어도 손실이 더 커질 수 있나요?","a":"가능합니다. 급락이나 갭 상황에서는 시장가 손절이 트리거보다 낮은 가격에 체결될 수 있고, 지정가 손절은 아예 체결되지 않을 수 있습니다."},{"q":"손절은 몇 퍼센트로 설정해야 하나요?","a":"고정된 정답은 없습니다. 코인의 변동성과 차트 구조에 맞춰 손절 위치를 정하고, 그 폭에서 감당할 손실 금액에 맞게 포지션 크기를 조절하는 것이 일반적입니다."}],"title":"손절 주문(스탑로스)이란? 뜻과 설정법","description":"손절 주문(스탑로스)의 뜻과 시장가·지정가 방식 차이, 선물 청산과의 관계, 손실 한도로 포지션 크기를 계산하는 방법을 설명합니다.","related":[["take-profit","익절 주문(Take-Profit)","익절 주문(테이크프로핏)은 가격이 미리 정한 목표 수준에 도달하면 자동으로 포지션을 정리해 이익을 확정하는 주문입니다."],["stop-limit-order","스탑 리밋 주문(Stop-Limit Order)","스탑 리밋 주문은 가격이 트리거(스탑) 가격에 도달하면 미리 정한 지정가 주문이 호가창에 올라가도록 하는 조건부 주문입니다."],["trailing-stop","트레일링 스탑(Trailing Stop)","트레일링 스탑은 가격이 유리하게 움직이면 손절 가격이 일정 간격을 유지하며 함께 따라 올라가고, 가격이 그 간격만큼 되돌리면 포지션을 정리하는 주문입니다."],["position-sizing","포지션 사이징(Position Sizing)","포지션 사이징은 한 번의 거래에서 잃어도 되는 금액을 먼저 정하고, 손절 거리에 맞춰 진입할 수량을 계산하는 자금 관리 방법입니다."],["liquidation","강제청산(Liquidation)","강제청산은 레버리지 포지션의 손실로 증거금이 유지 증거금 아래로 떨어졌을 때 거래소가 더 큰 손실을 막기 위해 포지션을 강제로 정리하는 것입니다."]],"lesson":{"id":"E17","slug":"stop-loss-is-a-plan","ep":17,"title":"익절과 손절은 계획이지 보험이 아니다"},"coin":null,"tool":"/liquidations","cta":false},"unrealized-pnl":{"slug":"unrealized-pnl","cat":"derivatives","en":"Unrealized PnL","contentLocale":"ko","term":"미실현 손익(Unrealized PnL)","aka":["평가 손익","미실현 PnL","unrealized PnL","평가손익"],"short":"미실현 손익은 아직 닫지 않은 포지션을 현재 가격으로 평가했을 때의 이익이나 손실로, 포지션을 청산해야 실현 손익으로 확정됩니다.","body":[["선물 포지션의 미실현 손익은 보통 ",["마크 가격","mark-price"]," 기준으로 계산합니다. 롱은 (마크 가격 − 진입가) × 수량, 숏은 (진입가 − 마크 가격) × 수량입니다. 앱에 함께 표시되는 수익률(ROE)은 이 손익을 증거금으로 나눈 값이라 ",["레버리지","leverage"],"가 높을수록 크게 보입니다."],[["교차 마진","cross-margin"],"에서는 한 포지션의 미실현 이익이 다른 포지션의 증거금으로 쓰이고, 미실현 손실은 계좌 전체의 증거금 여유를 줄입니다. 그래서 미실현 손익이 바뀔 때마다 ",["청산가","liquidation-price"],"도 함께 움직입니다."],"미실현 이익은 가격이 되돌아오면 사라질 수 있는 숫자입니다. 일부를 익절하거나 손절가를 진입가 근처로 올리는 방법으로 이익을 지키는 경우가 많습니다. 현물 보유분의 평가 손익도 같은 개념입니다."],"example":"ETH를 2,400 USDT에 3개 롱으로 진입했고, 현재 마크 가격이 2,520 USDT라고 가정해 보겠습니다. 미실현 손익은 (2,520 − 2,400) × 3 = 360 USDT입니다. 포지션 규모 7,200 USDT를 6배 레버리지로 열었다면 증거금은 1,200 USDT이므로 수익률은 30%로 표시됩니다. 이 상태에서 2개를 팔면 240 USDT가 실현 손익으로 확정되고, 남은 1개의 120 USDT는 여전히 미실현입니다.","mistakes":["미실현 이익을 이미 번 돈으로 생각해 그 이익을 근거로 포지션을 더 키웁니다.","ROE 수익률만 보고 실제 손익 금액을 확인하지 않습니다.","최근 체결가로 손익을 계산해 앱에 표시된 마크 가격 기준 손익과 다르다고 혼란스러워합니다."],"faq":[{"q":"미실현 손익과 실현 손익의 차이는 무엇인가요?","a":"미실현 손익은 열려 있는 포지션의 현재 평가 값이고, 실현 손익은 포지션을 닫아 확정된 값입니다. 수수료와 펀딩비는 보통 실현 손익에 반영됩니다."},{"q":"미실현 이익을 출금할 수 있나요?","a":"일반적으로는 포지션을 닫아 실현해야 출금할 수 있습니다. 일부 거래소는 교차 마진에서 미실현 이익을 증거금으로 쓰는 것만 허용합니다."}],"title":"미실현 손익이란? 평가 손익 계산법","description":"선물 거래의 미실현 손익(평가 손익) 뜻, 마크 가격 기준 계산법, 실현 손익과 ROE의 차이를 예시로 설명합니다.","related":[["mark-price","마크 가격(Mark Price)","마크 가격은 선물 거래소가 평가 손익과 강제청산을 계산할 때 쓰는 기준 가격으로, 여러 현물 거래소의 지수 가격을 바탕으로 만들어 순간적인 가격 조작의 영향을 줄입니다."],["cross-margin","교차 마진(Cross Margin)","교차 마진은 계좌의 사용 가능한 잔고 전체를 여러 포지션이 함께 증거금으로 쓰는 방식으로, 청산가는 멀어지지만 한 번 청산되면 계좌 잔고 대부분을 잃을 수 있습니다."],["liquidation-price","청산가(Liquidation Price)","청산가는 마크 가격이 그 수준에 닿으면 증거금이 유지 증거금 아래로 떨어져 포지션이 강제청산되는 가격입니다."],["take-profit","익절 주문(Take-Profit)","익절 주문(테이크프로핏)은 가격이 미리 정한 목표 수준에 도달하면 자동으로 포지션을 정리해 이익을 확정하는 주문입니다."]],"lesson":{"id":"E20","slug":"maintenance-margin","ep":20,"title":"증거금이 제로가 되기 전에 강제 종료될 수 있는 이유는?"},"coin":null,"tool":null,"cta":false},"cold-wallet":{"slug":"cold-wallet","cat":"wallets-security","en":"Cold wallet (cold storage)","contentLocale":"ko","term":"콜드월렛(Cold Wallet, 콜드 스토리지)","aka":["콜드 월렛","콜드 스토리지","오프라인 지갑","cold wallet"],"short":"콜드월렛은 개인 키를 인터넷과 분리된 환경에 보관해 온라인 해킹 위험을 크게 줄인 암호화폐 보관 방식입니다.","body":[[["하드웨어 지갑","hardware-wallet"],", 한 번도 인터넷에 연결하지 않은 기기, 종이에 적은 키처럼 ",["개인 키","private-key"],"가 온라인에 노출되지 않는 보관 방식을 통틀어 콜드월렛이라고 부릅니다. ",["거래소","centralized-exchange"],"도 고객 자산의 상당 부분을 콜드 스토리지에 두는 것이 일반적입니다."],["콜드월렛에서 송금하려면 거래를 오프라인 키로 서명한 뒤 네트워크에 전달해야 합니다. 그래서 ",["핫월렛","hot-wallet"],"보다 번거롭지만, 원격 공격자가 키를 직접 빼 가기 어렵습니다."],["콜드월렛이라고 위험이 없는 것은 아닙니다. ",["시드 문구","seed-phrase"],"를 잃어버리거나, 화재와 침수로 백업이 훼손되거나, 가짜 하드웨어 지갑을 사면 문제가 생깁니다. 백업은 두 곳 이상에 오프라인으로 나눠 두는 경우가 많습니다."]],"example":["1.2 BTC를 ",["장기 보유","hodl"],"하려는 사람이 거래소에서 콜드월렛 주소로 출금한다고 가정합니다. 송금 후 0.05 BTC만 매매용으로 거래소에 남기면, 나머지 1.15 BTC는 거래소 해킹이나 계정 탈취가 일어나도 영향을 받지 않습니다. 대신 나중에 팔 때는 콜드월렛에서 다시 거래소로 입금하고 블록 확인을 기다리는 시간이 필요합니다."],"mistakes":["콜드월렛 시드 문구를 컴퓨터 메모장에 입력해 저장하면서 오프라인 보관이라고 생각합니다.","중고 거래로 이미 초기화된 것처럼 보이는 하드웨어 지갑을 사서 그대로 씁니다.","백업을 한 장만 만들어 한 장소에 보관합니다."],"faq":[{"q":"콜드월렛과 하드웨어 지갑은 같은 말인가요?","a":"하드웨어 지갑은 콜드월렛을 구현하는 가장 흔한 방법입니다. 하지만 콜드월렛은 키를 오프라인에 두는 보관 방식 전체를 가리키는 더 넓은 개념입니다."},{"q":"콜드월렛에 있는 코인도 해킹될 수 있나요?","a":"원격 해킹은 매우 어렵지만 시드 문구가 유출되거나 사용자가 피싱 사이트에서 직접 서명하면 자산을 잃을 수 있습니다. 결국 키와 서명 관리가 핵심입니다."}],"title":"콜드월렛이란? 콜드 스토리지 뜻과 사용법","description":"콜드월렛(콜드 스토리지)의 뜻, 핫월렛과의 차이, 장기 보유 자산을 안전하게 보관하는 기본 원칙을 정리합니다.","related":[["hot-wallet","핫월렛(Hot Wallet)","핫월렛은 인터넷에 연결된 기기에서 개인 키를 관리해 바로 송금과 서명을 할 수 있는 온라인 상태의 암호화폐 지갑입니다."],["hardware-wallet","하드웨어 지갑(Hardware Wallet)","하드웨어 지갑은 개인 키를 전용 보안 기기 안에 보관하고 거래 서명도 기기 안에서 처리해 키가 컴퓨터나 휴대폰에 노출되지 않게 하는 지갑입니다."],["seed-phrase","시드 문구(Seed Phrase, 복구 문구)","시드 문구는 지갑을 만들 때 생성되는 12개 또는 24개의 영어 단어 목록으로, 이것만 있으면 지갑의 모든 개인 키와 자산을 복구할 수 있는 마스터 키입니다."],["multisig-wallet","멀티시그 지갑(Multisig Wallet)","멀티시그 지갑은 여러 개의 개인 키 가운데 정해진 수 이상이 함께 서명해야 송금할 수 있는 지갑으로, 키 하나가 유출돼도 자산을 옮길 수 없게 합니다."]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"내 코인은 어디에 있을까: 거래소 vs 지갑"},"coin":null,"tool":null,"cta":false},"rug-pull":{"slug":"rug-pull","cat":"wallets-security","en":"Rug pull","contentLocale":"ko","term":"러그풀(Rug Pull)","aka":["러그 풀","먹튀","rug pull"],"short":"러그풀은 프로젝트 개발자나 운영자가 투자자의 돈이 모이면 유동성을 빼 가거나 토큰을 대량 매도하고 사라지는 사기 행위입니다.","body":[["가장 흔한 형태는 ",["DEX","dex"]," ",["유동성 풀","liquidity-pool"],"에서 일어납니다. 개발자가 새 토큰과 ETH나 SOL을 묶어 풀을 만들고, 사람들이 토큰을 사서 풀에 기축 코인이 쌓이면 개발자가 ",["유동성","liquidity"],"을 회수해 버립니다. 그러면 토큰은 팔 상대가 없어져 가격이 거의 0이 됩니다."],["다른 형태로는 개발자가 보유한 대량의 물량을 한꺼번에 파는 덤핑, 그리고 ",["컨트랙트","smart-contract"],"에 판매 금지나 무한 발행 같은 숨은 기능을 넣어 두는 방식이 있습니다. ",["밈코인","memecoin"],"처럼 출시가 쉽고 정보가 적은 토큰에서 자주 보입니다."],["완벽히 피할 방법은 없지만 확인할 점은 있습니다. 유동성이 잠겨 있는지와 기간, 상위 보유 지갑 비중, 컨트랙트 소유권 포기 여부, 판매 제한이나 세금 설정을 ",["익스플로러","block-explorer"],"나 분석 도구로 봅니다."]],"example":"새 밈코인 풀에 개발자가 토큰 10억 개와 20 SOL을 넣고, 이후 매수세가 몰려 풀 안의 SOL이 400개까지 늘었다고 가정합니다. 개발자가 유동성 토큰을 사용해 풀을 회수하면 쌓인 SOL 대부분을 가져가고, 남은 투자자의 토큰은 바꿀 SOL이 거의 없어 가격이 99% 이상 떨어집니다. 투자자가 지갑에서 보는 토큰 개수는 그대로지만 팔 수 있는 가치는 사라진 것입니다.","mistakes":["커뮤니티 열기만 보고 유동성 잠금 여부를 확인하지 않습니다.","매수만 되고 매도는 막힌 허니팟 토큰을 소액 테스트 없이 크게 삽니다.","상위 몇 개 지갑이 공급량 대부분을 보유한 토큰을 분산이 잘된 토큰으로 착각합니다."],"faq":[{"q":"유동성이 잠겨 있으면 러그풀은 불가능한가요?","a":"유동성을 직접 빼는 것은 어려워지지만, 개발자 물량 덤핑이나 컨트랙트 숨은 기능을 통한 사기는 여전히 가능합니다. 잠금 기간이 짧으면 기간이 끝난 뒤 회수될 수도 있습니다."},{"q":"러그풀 당한 토큰을 되찾을 수 있나요?","a":"블록체인 거래는 되돌릴 수 없어 일반적으로 회수가 어렵습니다. 증거를 정리해 신고하는 것은 가능하지만 결과는 보장되지 않습니다."}],"title":"러그풀이란? 코인 먹튀 사기 확인법","description":"러그풀의 뜻과 대표 유형, 유동성 잠금과 보유 지갑 분포 등 매수 전에 확인할 위험 신호를 정리합니다.","related":[["memecoin","밈코인(Memecoin)","밈코인은 인터넷 밈이나 유머, 커뮤니티 문화를 바탕으로 만들어진 암호화폐로, 뚜렷한 기능보다 관심과 화제성이 가격을 크게 좌우하는 코인입니다."],["liquidity-pool","유동성 풀(Liquidity Pool)","유동성 풀은 DEX에서 거래가 가능하도록 두 가지 이상의 토큰을 스마트 컨트랙트에 함께 예치해 둔 자금 저장소로, 공급자는 거래 수수료를 나눠 받습니다."],["token-approval","토큰 승인(Token Approval, 허용량)","토큰 승인은 스마트 컨트랙트가 내 지갑의 특정 토큰을 정해진 한도만큼 대신 옮길 수 있도록 허락하는 서명으로, 한 번 주면 취소하기 전까지 유지됩니다."],["dex","탈중앙화 거래소(DEX)","탈중앙화 거래소(DEX)는 회사가 자산을 보관하지 않고 사용자가 개인 지갑에서 스마트 컨트랙트와 직접 토큰을 교환하는 거래소입니다."]],"lesson":{"id":"E11","slug":"scam-red-flags","ep":11,"title":"수익을 내주겠다는 사람이 있다면, 먼저 무엇을 요구하는지 보세요."},"coin":null,"tool":"/topics/meme-coins","cta":false},"oracle":{"slug":"oracle","cat":"defi","en":"Blockchain oracle","contentLocale":"ko","term":"블록체인 오라클(Oracle)","aka":["오라클","가격 오라클","oracle"],"short":"블록체인 오라클은 코인 가격, 환율, 경기 결과처럼 블록체인 밖에 있는 데이터를 스마트 컨트랙트가 읽을 수 있도록 체인 위로 전달하는 시스템입니다.","body":[[["스마트 컨트랙트","smart-contract"],"는 스스로 인터넷에 접속해 가격을 조회할 수 없습니다. 그래서 ",["디파이 대출","defi-lending"],", ",["무기한 선물 DEX","perp-dex"],", ",["스테이블코인","stablecoin"],"은 오라클이 올려 주는 가격을 기준으로 담보 가치와 청산 여부를 계산합니다. 체인링크(Chainlink)가 가장 널리 쓰이는 오라클 네트워크이고, 피스(Pyth) 등도 있습니다."],["좋은 오라클은 여러 ",["거래소","centralized-exchange"],"와 데이터 제공자의 가격을 모아 중앙값을 내고, 여러 ",["노드","node"],"가 독립적으로 보고하게 해 한 곳의 오류나 조작에 흔들리지 않게 설계됩니다."],"반대로 유동성이 얕은 한 DEX 가격만 그대로 읽는 오라클은 조작되기 쉽습니다. 실제로 짧은 시간 가격을 왜곡해 대출 프로토콜에서 과도하게 빌려 간 사고가 여러 번 있었습니다. 프로토콜을 고를 때 어떤 오라클을 쓰는지도 확인할 만한 항목입니다."],"example":"ETH가 2,500 USDC일 때 4 ETH를 담보로 7,000 USDC를 빌렸고 청산 기준이 80%라고 가정합니다. 담보의 청산 기준 가치는 10,000 곱하기 0.8로 8,000 USDC라 아직 여유가 있습니다. 그런데 오라클이 조작된 가격 2,150 USDC를 보고하면 담보 가치는 8,600 USDC, 청산 기준 가치는 6,880 USDC가 되어 대출 7,000 USDC보다 작아지고, 실제 시장 가격과 무관하게 청산이 실행됩니다.","mistakes":["디파이 프로토콜이 거래소 시세를 직접 실시간으로 본다고 생각합니다.","어떤 오라클을 쓰는지 확인하지 않고 작은 프로토콜에 큰 담보를 맡깁니다.","오라클 가격과 내가 보는 거래소 가격이 언제나 똑같다고 믿습니다."],"faq":[{"q":"오라클 문제란 무엇인가요?","a":"블록체인은 외부 데이터를 스스로 검증하지 못하므로, 데이터를 전달하는 오라클을 얼마나 믿을 수 있는지가 시스템 전체의 약점이 될 수 있다는 문제입니다."},{"q":"체인링크는 무엇을 하나요?","a":"여러 독립 노드가 외부 데이터를 모아 체인 위에 제공하는 탈중앙화 오라클 네트워크입니다. 많은 디파이 프로토콜이 가격 데이터 출처로 사용합니다."}],"title":"블록체인 오라클이란? 체인링크와 가격 조작","description":"블록체인 오라클의 뜻과 디파이에서의 역할, 체인링크 같은 오라클 네트워크, 가격 조작이 청산으로 이어지는 과정을 설명합니다.","related":[["smart-contract","스마트 컨트랙트(Smart Contract)","스마트 컨트랙트는 블록체인에 배포되어 미리 정한 조건이 충족되면 자동으로 실행되는 프로그램으로, 중개자 없이 거래와 규칙을 처리합니다."],["defi-lending","디파이 대출(DeFi Lending)","디파이 대출은 에이브(Aave)나 컴파운드 같은 프로토콜에 코인을 예치해 이자를 받거나, 담보를 맡기고 다른 코인을 빌리는 스마트 컨트랙트 기반 대출 서비스입니다."],["index-price","지수 가격(Index Price)","지수 가격은 여러 주요 현물 거래소의 가격을 가중 평균해 만든 기준 가격으로, 선물의 마크 가격과 펀딩비를 계산하는 바탕이 됩니다."],["flash-loan","플래시 론(Flash Loan)","플래시 론은 담보 없이 큰 금액을 빌리되 같은 블록체인 거래 안에서 바로 갚아야 하는 대출로, 갚지 못하면 거래 전체가 취소됩니다."]],"lesson":null,"coin":{"slug":"chainlink","name":"Chainlink","symbol":"LINK"},"tool":null,"cta":false},"launchpad":{"slug":"launchpad","cat":"exchange-features","en":"Launchpad (token sale)","contentLocale":"ko","term":"런치패드(Launchpad)","aka":["런치패드","토큰 세일","IEO","Launchpad"],"short":"런치패드는 거래소나 플랫폼이 신규 프로젝트의 토큰을 상장 전에 정해진 가격으로 사용자에게 판매하는 토큰 세일 서비스입니다.","body":[[["거래소","centralized-exchange"],"가 진행하는 토큰 세일을 IEO라고도 부릅니다. 보통 사전에 일정 기간 거래소 토큰이나 지정 자산을 보유한 실적에 따라 참여 한도가 정해지고, 신청이 몰리면 추첨이나 비례 배분으로 실제 구매 수량이 결정됩니다. 남은 신청 금액은 돌려줍니다."],["세일 가격이 상장 후 거래 가격보다 낮으면 수익이 나지만, 반대의 경우도 흔합니다. 특히 전체 공급량 중 세일 물량이 작고 나머지가 팀과 투자자에게 배정되어 있다면, ",["토큰 언락","token-unlock"]," 일정에 따라 시간이 지나며 매도 물량이 크게 늘 수 있습니다."],["참여 전에 확인할 것은 토큰 사용처, 전체 공급량과 ",["유통량","circulating-supply"],", 언락 일정, 세일 가격 기준 ",["시가총액","market-capitalization"],"입니다. 거래소 외부의 런치패드 플랫폼은 심사 수준이 제각각이므로 더 신중해야 합니다."]],"example":["토큰 세일 가격이 0.05 USDT이고 1,000 USDT를 신청했는데 신청이 10배 몰려 비례 배분으로 100 USDT만 체결되었다고 가정합니다. 받은 토큰은 2,000개이고 나머지 900 USDT는 반환됩니다. 상장 첫날 0.15 USDT가 되면 평가액은 300 USDT로 200 ",["USDT","usdt"]," 이익이지만, 0.03 USDT까지 떨어지면 60 USDT로 40 USDT 손실입니다. 신청 금액 전체가 체결되지 않는다는 점을 함께 고려해야 합니다."],"mistakes":["신청 금액 전부가 체결될 것으로 계산합니다.","언락 일정과 유통량을 보지 않고 세일 가격만으로 싸다고 판단합니다.","공식 거래소 공지가 아닌 메신저 링크로 런치패드 참여를 신청합니다."],"faq":[{"q":"런치패드 토큰은 상장하면 무조건 오르나요?","a":"그렇지 않습니다. 상장 직후 세일 가격 아래로 거래되는 경우도 있으며, 언락 물량이 풀리면서 가격이 압박받을 수 있습니다."},{"q":"런치패드 참여 자격은 어떻게 정해지나요?","a":"거래소마다 다르지만 보통 일정 기간 거래소 토큰이나 지정 자산을 보유한 실적, KYC 완료 여부, 거주 지역으로 결정됩니다."}],"title":"런치패드란? 거래소 토큰 세일(IEO) 참여 방법","description":"런치패드(토큰 세일)의 뜻, 비례 배분 방식, 상장 후 손익 계산과 참여 전 확인할 점을 설명합니다.","related":[["launchpool","런치풀(Launchpool)","런치풀은 거래소가 신규 토큰을 상장하기 전후에 사용자가 BNB나 USDT 등 지정 자산을 맡겨 두면 그 비율에 따라 새 토큰을 나눠 주는 이벤트입니다."],["token-listing","토큰 상장(Token listing)","토큰 상장은 거래소가 심사를 거쳐 새로운 코인이나 토큰의 입금, 거래 페어, 출금을 열어 사용자가 사고팔 수 있게 하는 것입니다."],["token-unlock","토큰 언락(Token Unlock)","토큰 언락은 팀, 투자자, 생태계 기금 등에게 배분된 뒤 잠겨 있던 토큰이 정해진 일정에 따라 풀려 거래 가능한 상태가 되는 것입니다."],["airdrop","에어드랍(Airdrop)","에어드랍은 프로젝트가 홍보, 커뮤니티 보상, 탈중앙화 분배를 위해 특정 조건을 만족한 지갑에 토큰을 무료로 나눠 주는 것입니다."]],"lesson":null,"coin":null,"tool":"/activities","cta":false},"sub-account":{"slug":"sub-account","cat":"exchange-features","en":"Sub-account","contentLocale":"ko","term":"서브 계정(Sub-account)","aka":["하위 계정","부계정","Sub-account"],"short":"서브 계정은 하나의 메인 계정 아래에 만드는 별도 거래 계정으로, 자금과 포지션, API 키를 전략별로 분리해 관리할 수 있게 해 줍니다.","body":[["메인 계정에서 서브 계정을 만들면 각 서브 계정은 독립된 잔고와 포지션을 가집니다. ",["장기 보유","hodl"],"용, 단기 선물용, 봇 전용처럼 목적에 따라 자금을 나누면 한 전략의 손실이 다른 전략의 증거금을 끌어가지 않습니다. 메인과 서브 사이 자금 이동은 보통 수수료 없이 즉시 처리됩니다."],["자동매매 프로그램을 쓸 때 특히 유용합니다. 봇 전용 서브 계정에만 API 키를 발급하고 출금 권한을 빼 두면, 키가 유출되어도 피해 범위가 그 계정 자금으로 줄어듭니다. ",["카피 트레이딩","copy-trading"],"도 별도 서브 계정에서 돌리면 성과를 따로 보기 쉽습니다."],["서브 계정은 메인 계정의 KYC를 공유하며, ",["수수료 등급","vip-tier"],"도 메인 계정 기준으로 합산되는 경우가 많습니다. 생성 가능 개수, 서브 계정의 출금 가능 여부, 로그인 방식은 ",["거래소","centralized-exchange"],"마다 다릅니다."]],"example":["총 10,000 USDT를 운용하면서 메인 계정에 7,000 USDT를 현물로 두고, 서브 계정 A에 2,000 USDT로 선물 거래를, 서브 계정 B에 1,000 USDT로 ",["그리드 봇","grid-trading-bot"],"을 돌린다고 가정합니다. A에서 급락으로 2,000 ",["USDT","usdt"]," 전액이 청산되어도 손실은 전체의 20%에서 멈추고, 메인의 7,000 USDT와 B의 1,000 USDT는 영향을 받지 않습니다. 하나의 계정에 모두 두었다면 같은 급락에 더 많은 자금이 증거금으로 묶였을 수 있습니다."],"mistakes":["봇용 API 키를 메인 계정에서 출금 권한까지 켜고 발급합니다.","서브 계정이 메인 계정과 다른 사람 명의로 쓸 수 있다고 생각해 타인에게 빌려줍니다.","서브 계정별 잔고를 따로 확인하지 않아 전체 노출 금액을 잘못 계산합니다."],"faq":[{"q":"서브 계정을 만들면 KYC를 다시 해야 하나요?","a":"대개 메인 계정의 KYC를 그대로 사용합니다. 서브 계정은 같은 사용자의 하위 계정이라 별도 명의로 쓰면 안 됩니다."},{"q":"서브 계정 사이 자금 이동에 수수료가 있나요?","a":"대부분의 거래소에서 메인과 서브 계정 간 이체는 수수료 없이 즉시 처리됩니다. 세부 조건은 거래소마다 다릅니다."}],"title":"서브 계정이란? 전략별 자금 분리와 API 보안","description":"거래소 서브 계정의 뜻, 전략별로 자금과 위험을 나누는 법, API 키를 안전하게 쓰는 방법을 설명합니다.","related":[["unified-trading-account","통합 거래 계정(UTA)","통합 거래 계정은 현물, 선물, 옵션 거래를 하나의 계정 잔고와 증거금으로 함께 운용할 수 있게 묶은 거래소 계정 방식입니다."],["isolated-margin","격리 마진(Isolated Margin)","격리 마진은 포지션마다 증거금을 따로 배정해, 그 포지션이 청산되더라도 배정한 증거금만 잃고 계좌의 나머지 잔고는 영향을 받지 않는 마진 방식입니다."],["two-factor-authentication","2단계 인증(2FA, OTP)","2단계 인증(2FA)은 비밀번호 외에 OTP 앱 코드나 보안 키 같은 두 번째 수단을 추가로 요구해 계정 탈취를 어렵게 만드는 보안 기능입니다."],["copy-trading","카피 트레이딩(Copy trading)","카피 트레이딩은 다른 트레이더(리드 트레이더)의 매매를 내 계정에서 정해진 비율이나 금액으로 자동으로 따라 하는 거래소 기능입니다."]],"lesson":null,"coin":null,"tool":null,"cta":false},"vip-tier":{"slug":"vip-tier","cat":"exchange-features","en":"VIP fee tier","contentLocale":"ko","term":"VIP 수수료 등급","aka":["VIP 등급","수수료 등급","VIP tier"],"short":"VIP 수수료 등급은 거래소가 최근 거래량이나 보유 자산 규모에 따라 사용자를 단계별로 나누고 높은 등급일수록 낮은 메이커·테이커 수수료를 적용하는 제도입니다.","body":[["보통 최근 30일 ",["거래량","trading-volume"],"과 계정 자산 잔고, 또는 ",["거래소","centralized-exchange"]," 토큰 보유량을 기준으로 등급이 정해집니다. 등급이 오를수록 수수료율이 낮아지고, 상위 등급에서는 출금 한도 확대나 전담 매니저 같은 혜택이 붙기도 합니다. 현물과 선물의 등급 기준이 따로 있는 경우가 많습니다."],"일반 사용자에게는 기본 등급이 적용되며, 상위 등급에 필요한 거래량은 상당히 큽니다. 등급을 맞추려고 불필요한 거래를 늘리면 수수료 절감보다 손실이 더 커질 수 있으므로, 자신의 실제 거래 규모에서 현실적으로 닿는 등급인지 먼저 확인해야 합니다.",["등급 산정 주기, ",["서브 계정","sub-account"]," 합산 여부, 다른 거래소의 등급을 인정해 주는 이벤트 등은 거래소마다 다릅니다. 거래소의 수수료 안내 페이지에서 현재 기준을 확인하세요."]],"example":["어떤 거래소의 기본 등급 선물 ",["테이커 수수료","maker-taker-fees"],"가 0.05%, 다음 등급이 0.045%이고, 다음 등급 기준이 30일 거래량 1,000만 USDT라고 가정합니다. 내 월 거래량이 800만 USDT라면 기본 등급에서 4,000 USDT를 수수료로 냅니다. 같은 거래량에 0.045%가 적용되면 3,600 USDT로 400 USDT를 아낍니다. 하지만 등급을 맞추려고 200만 USDT를 더 거래하면 그 추가 거래 수수료만 900 USDT가 들어 오히려 손해입니다."],"mistakes":["VIP 등급을 달성하려고 계획에 없던 거래를 늘립니다.","현물과 선물 등급 기준이 같다고 생각합니다.","등급 산정이 끝나는 시점을 확인하지 않아 등급이 내려간 것을 모르고 거래합니다."],"faq":[{"q":"VIP 등급은 어떻게 올리나요?","a":"대개 최근 30일 거래량이나 계정 자산 규모 중 하나의 기준을 넘으면 오릅니다. 구체적인 기준은 거래소 수수료 페이지에 나와 있습니다."},{"q":"VIP 등급과 레퍼럴 할인은 함께 적용되나요?","a":"거래소마다 다릅니다. 둘 다 적용되는 경우도 있고, 일정 등급 이상에서는 레퍼럴 혜택이 달라지는 경우도 있습니다."}],"title":"VIP 수수료 등급이란? 거래량별 수수료 할인 구조","description":"거래소 VIP 수수료 등급의 뜻, 등급 산정 기준, 등급을 맞추려 거래를 늘릴 때 손해가 나는 이유를 설명합니다.","related":[["maker-taker-fees","메이커·테이커 수수료(Maker/Taker Fee)","메이커·테이커 수수료는 호가창에 새 주문을 걸어 유동성을 공급한 쪽(메이커)과 이미 걸린 주문을 즉시 체결한 쪽(테이커)에 서로 다르게 매기는 거래 수수료입니다."],["referral-code","레퍼럴 코드(수수료 페이백)","레퍼럴 코드는 거래소 가입 시 입력하는 추천 코드로, 연결된 계정의 거래 수수료 일부를 사용자에게 할인이나 페이백 형태로 돌려주는 데 쓰입니다."],["trading-volume","거래량(Trading Volume)","거래량은 일정 기간 동안 실제로 체결된 코인의 수량 또는 금액을 말하며, 보통 24시간 기준으로 시장의 관심과 활발함을 보여 줍니다."],["market-maker","마켓메이커(Market Maker)","마켓메이커는 매수 호가와 매도 호가를 동시에 꾸준히 걸어 두어 다른 사람이 언제든 거래할 수 있도록 유동성을 공급하는 참여자입니다."]],"lesson":null,"coin":null,"tool":"/rates","cta":false},"token-listing":{"slug":"token-listing","cat":"exchange-features","en":"Token listing","contentLocale":"ko","term":"토큰 상장(Token listing)","aka":["코인 상장","상장","신규 상장","Token listing"],"short":"토큰 상장은 거래소가 심사를 거쳐 새로운 코인이나 토큰의 입금, 거래 페어, 출금을 열어 사용자가 사고팔 수 있게 하는 것입니다.","body":[[["거래소","centralized-exchange"],"는 프로젝트의 기술, 팀, 토큰 분배, 법적 위험, ",["유동성","liquidity"]," 등을 검토한 뒤 상장을 결정합니다. 상장 공지에는 보통 입금 개시 시각, 거래 시작 시각, ",["거래 페어","trading-pair"],", 출금 개시 시각이 나옵니다. 일부 거래소는 위험도가 높은 신규 토큰을 별도 구역에 두고 주의 표시를 붙입니다."],["상장 직후에는 가격 변동이 극단적인 경우가 많습니다. 처음 몇 분은 호가가 얇아 ",["시장가 주문","market-order"],"이 크게 미끄러지고, ",["에어드랍","airdrop"],"이나 ",["런치풀","launchpool"]," 보상을 받은 사람들의 매도 물량이 한꺼번에 나올 수 있습니다. 상장 소식만으로 가격이 급등했다가 빠르게 되돌아가는 경우도 흔합니다."],"상장은 거래소가 거래를 허용했다는 뜻일 뿐 가치나 안전성을 보증하는 것은 아닙니다. 같은 이름의 가짜 토큰이 탈중앙 거래소에 먼저 올라오기도 하므로, 컨트랙트 주소는 거래소나 프로젝트 공식 채널에서 확인해야 합니다."],"example":"새 토큰이 상장되고 첫 1분 동안 매도 호가가 1.00, 1.10, 1.25 USDT에 각각 1,000개씩만 있다고 가정합니다. 2,500 USDT로 시장가 매수를 하면 1,000개를 1,000 USDT에, 1,000개를 1,100 USDT에 사고, 남은 400 USDT로 1.25 USDT에 320개를 삽니다. 총 2,320개, 평균 단가는 약 1.08 USDT로 첫 호가보다 8% 비쌉니다. 지정가 주문을 썼다면 이런 미끄러짐을 피할 수 있었습니다.","mistakes":["상장 직후 얇은 호가창에 큰 시장가 주문을 넣습니다.","거래소 상장을 프로젝트의 안전성 보증으로 받아들입니다.","공식 채널 확인 없이 같은 이름의 토큰을 탈중앙 거래소에서 미리 삽니다."],"faq":[{"q":"상장 소식이 나면 가격이 오르나요?","a":"일시적으로 오르는 경우가 있지만 거래 시작 후 빠르게 되돌아가기도 합니다. 상장 자체가 가격 방향을 정하지는 않습니다."},{"q":"상장 일정은 어디서 확인하나요?","a":"거래소 공식 공지 페이지와 공식 소셜 계정에서 확인할 수 있습니다. 출처가 불분명한 상장 루머는 주의해야 합니다."}],"title":"토큰 상장이란? 거래소 신규 상장 과정과 주의점","description":"토큰 상장의 뜻, 거래소 상장 공지 읽는 법, 상장 직후 시장가 주문이 위험한 이유를 계산 예시로 설명합니다.","related":[["delisting","상장폐지(Delisting)","상장폐지는 거래소가 특정 코인의 거래 페어를 닫고 일정 기간 뒤 입출금 지원까지 종료하는 것으로, 국내 거래소에서는 거래 지원 종료라고도 부릅니다."],["launchpool","런치풀(Launchpool)","런치풀은 거래소가 신규 토큰을 상장하기 전후에 사용자가 BNB나 USDT 등 지정 자산을 맡겨 두면 그 비율에 따라 새 토큰을 나눠 주는 이벤트입니다."],["liquidity","유동성(Liquidity)","유동성은 원하는 수량의 자산을 가격을 크게 움직이지 않고 빠르게 사고팔 수 있는 정도를 뜻하며, 호가창의 두께와 스프레드로 확인할 수 있습니다."],["altcoin","알트코인(Altcoin)","알트코인은 비트코인을 제외한 나머지 암호화폐를 통틀어 부르는 말로, 이더리움, 솔라나, XRP 같은 대형 코인부터 소형 토큰까지 모두 포함합니다."]],"lesson":null,"coin":null,"tool":"/activities","cta":false},"stock-perpetuals":{"slug":"stock-perpetuals","cat":"tokenized-assets","en":"Stock perpetuals","contentLocale":"ko","term":"주식 무기한 선물","aka":["주식 퍼프","주식 영구 선물","Stock perpetuals"],"short":"주식 무기한 선물은 테슬라나 엔비디아 같은 주식의 가격을 추종하는 만기 없는 선물 계약으로, USDT 증거금과 레버리지로 롱과 숏을 거래합니다.","body":[[["암호화폐","cryptocurrency"]," ",["무기한 선물","perpetual-futures"],"과 같은 구조를 주식 가격에 적용한 상품입니다. 실제 주식을 소유하지 않고 가격 변동만 거래하며, 계약 가격이 기준 가격에서 너무 멀어지지 않도록 ",["롱과 숏","long-and-short"]," 사이에 ",["펀딩비","funding-rate"],"를 주고받습니다. 일부 ",["중앙화 거래소","centralized-exchange"],"와 하이퍼리퀴드 같은 온체인 파생상품 거래소에서 이런 상품이 나오고 있습니다."],["가장 큰 차이는 거래 시간입니다. 무기한 선물은 24시간 열려 있지만 기준이 되는 주식 시장은 정해진 시간에만 열립니다. 휴장 중에는 가격 산정 방식이 달라지거나 변동 폭을 제한하는 경우가 있고, 개장 시 갭이 생기면 ",["레버리지","leverage"]," 포지션이 한 번에 청산될 수 있습니다."],"배당, 주식 분할, 거래 정지 같은 기업 이벤트를 어떻게 처리하는지, 휴장 시간의 마크 가격을 어떻게 계산하는지는 거래소마다 다릅니다. 계약 사양 페이지를 먼저 확인해야 합니다."],"example":"어떤 주식이 250달러일 때 5배 레버리지로 1,000 USDT 증거금 롱, 즉 5,000 USDT 규모 포지션을 열었다고 가정합니다. 주말 동안 악재가 나와 월요일 개장 가격이 215달러, 14% 하락으로 시작하면 손실은 5,000 × 14% = 700 USDT입니다. 유지 증거금이 포지션 규모의 2%인 100 USDT라면 남은 증거금 300 USDT로는 아직 버티지만, 레버리지가 10배였다면 손실이 1,400 USDT로 증거금 1,000 USDT를 넘어 이미 청산됐을 것입니다.","mistakes":["24시간 거래된다는 이유로 휴장 시간 갭 위험을 잊습니다.","주식 무기한 선물을 보유하면 배당이나 주주 권리가 생긴다고 생각합니다.","펀딩비를 확인하지 않고 포지션을 몇 주씩 유지합니다."],"faq":[{"q":"주식 무기한 선물은 실제 주식을 사는 건가요?","a":"아닙니다. 주가를 추종하는 파생 계약일 뿐 주식 소유권이나 의결권은 없습니다."},{"q":"주식 시장이 닫히면 주식 무기한 선물은 어떻게 되나요?","a":"거래는 계속되는 경우가 많지만 마크 가격 산정 방식이 달라질 수 있습니다. 개장 시 가격이 크게 벌어지면 청산 위험이 커집니다."}],"title":"주식 무기한 선물이란? 구조와 휴장 갭 위험","description":"주식 무기한 선물의 뜻, 토큰화 주식과의 차이, 펀딩비와 휴장 시간 갭으로 청산되는 과정을 설명합니다.","related":[["tokenized-stocks","토큰화 주식(Tokenized stocks)","토큰화 주식은 실제 주식이나 그 가격을 따라가는 권리를 블록체인 토큰으로 발행해 암호화폐처럼 지갑과 거래소에서 거래할 수 있게 만든 자산입니다."],["perpetual-futures","무기한 선물(Perpetual Futures)","무기한 선물은 만기일 없이 원하는 만큼 포지션을 유지할 수 있는 선물 계약으로, 펀딩비를 주고받아 가격이 현물 가격 근처에 머물도록 설계되어 있습니다."],["funding-rate","펀딩비(Funding Rate)","펀딩비는 무기한 선물에서 롱과 숏 포지션 보유자가 일정 간격마다 서로 주고받는 비용으로, 선물 가격이 현물 가격에서 크게 벗어나지 않도록 하는 장치입니다."],["leverage","레버리지(Leverage)","레버리지는 맡긴 증거금보다 몇 배 큰 규모의 포지션을 거래하는 것으로, 수익과 손실이 모두 그 배수만큼 커지고 강제청산 위험도 함께 커집니다."]],"lesson":null,"coin":null,"tool":"/topics/tokenized-stocks-vs-perpetuals","cta":true}});
